const config = {
  "previewFeatures": [
    "fullTextSearchPostgres",
    "postgresqlExtensions"
  ],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// Fixit247BM — Prisma Schema\n// Premium Australian emergency trade services platform\n\ngenerator client {\n  provider        = \"prisma-client-js\"\n  output          = \"../src/generated/client\"\n  previewFeatures = [\"postgresqlExtensions\", \"fullTextSearchPostgres\"]\n}\n\ndatasource db {\n  provider   = \"postgresql\"\n  extensions = [postgis, uuid_ossp(map: \"uuid-ossp\"), pg_trgm]\n}\n\n// ─── Enums ────────────────────────────────────────────────────────────────────\n\nenum Role {\n  CUSTOMER\n  TRADIE\n  ADMIN\n  SUPER_ADMIN\n}\n\nenum JobStatus {\n  DRAFT\n  OPEN\n  CLAIMED\n  IN_PROGRESS\n  PENDING_REVIEW\n  COMPLETED\n  CANCELLED\n  DISPUTED\n}\n\nenum JobPriority {\n  STANDARD\n  URGENT\n  EMERGENCY\n}\n\nenum TradeCategory {\n  PLUMBING\n  ELECTRICAL\n  HVAC\n  CARPENTRY\n  PAINTING\n  ROOFING\n  TILING\n  PEST_CONTROL\n  LOCKSMITH\n  GLAZING\n  PLASTERING\n  LANDSCAPING\n  CLEANING\n  APPLIANCE_REPAIR\n  GENERAL_MAINTENANCE\n  OTHER\n}\n\nenum VerificationStatus {\n  UNVERIFIED\n  PENDING\n  VERIFIED\n  REJECTED\n  SUSPENDED\n}\n\nenum PaymentStatus {\n  PENDING\n  PROCESSING\n  HELD_IN_ESCROW\n  RELEASED\n  REFUNDED\n  DISPUTED\n  FAILED\n}\n\nenum NotificationType {\n  JOB_CREATED\n  JOB_ASSIGNED\n  JOB_ACCEPTED\n  JOB_DECLINED\n  TRADIE_EN_ROUTE\n  TRADIE_ARRIVED\n  JOB_STARTED\n  JOB_COMPLETED\n  PAYMENT_HELD\n  PAYMENT_RELEASED\n  PAYMENT_FAILED\n  DISPUTE_OPENED\n  DISPUTE_RESOLVED\n  NEW_MESSAGE\n  CREDIT_LOW\n  SUBSCRIPTION_RENEWED\n  VERIFICATION_APPROVED\n  VERIFICATION_REJECTED\n  SYSTEM_ALERT\n}\n\nenum OnboardingStatus {\n  INCOMPLETE\n  PENDING_REVIEW\n  APPROVED\n  REJECTED\n}\n\nenum TradeBadge {\n  VERIFIED\n  PREMIUM\n  ELITE\n  EMERGENCY_SPECIALIST\n  TOP_RATED\n}\n\nenum AuditAction {\n  LOGIN\n  LOGOUT\n  REGISTER\n  PASSWORD_RESET\n  EMAIL_VERIFIED\n  ROLE_CHANGED\n  PROFILE_UPDATED\n  DOCUMENT_UPLOADED\n  VERIFICATION_APPROVED\n  VERIFICATION_REJECTED\n  PAYMENT_INITIATED\n  PAYMENT_RELEASED\n  JOB_CREATED\n  JOB_CLAIMED\n  JOB_COMPLETED\n  DISPUTE_OPENED\n  DISPUTE_RESOLVED\n  ACCOUNT_SUSPENDED\n  ACCOUNT_REINSTATED\n}\n\nenum SubscriptionTier {\n  FREE\n  BASIC\n  PROFESSIONAL\n  ELITE\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  PAUSED\n  EXPIRED\n  PAST_DUE\n}\n\nenum TransactionType {\n  PAYMENT\n  PAYOUT\n  REFUND\n  PLATFORM_FEE\n  CREDIT\n  DEBIT\n}\n\n// ─── Core Models ──────────────────────────────────────────────────────────────\n\nmodel User {\n  id                 String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  email              String    @unique\n  emailVerified      DateTime?\n  phone              String?\n  phoneVerified      Boolean   @default(false)\n  role               Role      @default(CUSTOMER)\n  firstName          String\n  lastName           String\n  avatarUrl          String?\n  isActive           Boolean   @default(true)\n  onboardingComplete Boolean   @default(false)\n  lastLoginAt        DateTime?\n  loginCount         Int       @default(0)\n  lastIpAddress      String?\n  deletedAt          DateTime?\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  // Relations\n  customerProfile   CustomerProfile?\n  tradieProfile     TradieProfile?\n  sessions          Session[]\n  auditLogs         AuditLog[]\n  reviewsGiven      Review[]         @relation(\"ReviewsGiven\")\n  reviewsReceived   Review[]         @relation(\"ReviewsReceived\")\n  addresses         Address[]\n  subscription      Subscription?\n  creditsWallet     CreditsWallet?\n  referralsSent     Referral[]       @relation(\"ReferralInviter\")\n  referralsReceived Referral[]       @relation(\"ReferralInvited\")\n  voiceCalls        VoiceCall[]      @relation(\"CustomerVoiceCalls\")\n\n  @@index([email])\n  @@index([role])\n  @@index([isActive])\n  @@index([deletedAt])\n  @@index([createdAt])\n  @@map(\"users\")\n}\n\nmodel Session {\n  id           String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId       String   @db.Uuid\n  token        String   @unique\n  refreshToken String?\n  expiresAt    DateTime\n  ipAddress    String?\n  userAgent    String?\n  deviceType   String?\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  lastUsedAt   DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([token])\n  @@index([expiresAt])\n  @@map(\"sessions\")\n}\n\nmodel AuditLog {\n  id         String      @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId     String?     @db.Uuid\n  action     AuditAction\n  resource   String?\n  resourceId String?\n  ipAddress  String?\n  userAgent  String?\n  metadata   Json?\n  createdAt  DateTime    @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([userId])\n  @@index([action])\n  @@index([resource, resourceId])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ─── Profile Models ───────────────────────────────────────────────────────────\n\nmodel CustomerProfile {\n  id                    String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId                String   @unique @db.Uuid\n  suburb                String?\n  postcode              String?\n  state                 String?\n  defaultAddressId      String?  @db.Uuid\n  emergencyContactName  String?\n  emergencyContactPhone String?\n  notifyBySms           Boolean  @default(true)\n  notifyByEmail         Boolean  @default(true)\n  notifyByPush          Boolean  @default(true)\n  creditBalance         Decimal  @default(0) @db.Decimal(10, 2)\n  jobsPosted            Int      @default(0)\n  totalSpent            Decimal  @default(0) @db.Decimal(12, 2)\n  createdAt             DateTime @default(now())\n  updatedAt             DateTime @updatedAt\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  addresses    Address[]     @relation(\"CustomerAddresses\")\n  savedTradies SavedTradie[]\n  jobs         Job[]         @relation(\"CustomerJobs\")\n\n  @@index([userId])\n  @@map(\"customer_profiles\")\n}\n\nmodel TradieProfile {\n  id                   String             @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId               String             @unique @db.Uuid\n  businessName         String?\n  abn                  String?            @unique\n  bio                  String?            @db.Text\n  trades               TradeCategory[]\n  yearsExperience      Int?\n  hourlyRate           Decimal?           @db.Decimal(10, 2)\n  calloutFee           Decimal?           @db.Decimal(10, 2)\n  serviceRadiusKm      Int                @default(25)\n  isAvailable          Boolean            @default(true)\n  isEmergencyAvailable Boolean            @default(false)\n  acceptsSameDay       Boolean            @default(false)\n  verificationStatus   VerificationStatus @default(UNVERIFIED)\n  onboardingStatus     OnboardingStatus   @default(INCOMPLETE)\n  onboardingStep       Int                @default(1)\n  stripeAccountId      String?            @unique\n  stripeOnboardingDone Boolean            @default(false)\n  avgRating            Decimal            @default(0) @db.Decimal(3, 2)\n  totalReviews         Int                @default(0)\n  totalJobsCompleted   Int                @default(0)\n  totalEarnings        Decimal            @default(0) @db.Decimal(12, 2)\n  responseTimeMinutes  Int?\n  completionRate       Decimal            @default(100) @db.Decimal(5, 2)\n  cancellationRate     Decimal            @default(0) @db.Decimal(5, 2)\n  trustScore           Decimal            @default(0) @db.Decimal(5, 2)\n  trustBadges          TradeBadge[]\n  isVisible            Boolean            @default(false)\n  isFeatured           Boolean            @default(false)\n  rankScore            Decimal            @default(0) @db.Decimal(10, 4)\n  createdAt            DateTime           @default(now())\n  updatedAt            DateTime           @updatedAt\n\n  user              User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  licences          Licence[]\n  insurances        Insurance[]\n  certifications    Certification[]\n  portfolios        TradiePortfolio[]\n  availability      Availability[]\n  emergencySettings EmergencySettings?\n  documents         TradieDocument[]\n  jobs              Job[]              @relation(\"TradieJobs\")\n  jobClaims         JobClaim[]\n\n  @@index([verificationStatus])\n  @@index([isAvailable])\n  @@index([isEmergencyAvailable])\n  @@index([isFeatured])\n  @@index([rankScore])\n  @@index([avgRating])\n  // Composite for matching engine: find available verified tradies\n  @@index([isAvailable, verificationStatus])\n  @@index([isEmergencyAvailable, verificationStatus])\n  @@map(\"tradie_profiles\")\n}\n\nmodel TradieDocument {\n  id          String             @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId    String             @db.Uuid\n  type        String\n  fileName    String\n  fileUrl     String\n  fileSize    Int?\n  mimeType    String?\n  status      VerificationStatus @default(PENDING)\n  reviewedBy  String?\n  reviewNotes String?\n  expiresAt   DateTime?\n  uploadedAt  DateTime           @default(now())\n  verifiedAt  DateTime?\n\n  tradie TradieProfile @relation(fields: [tradieId], references: [id], onDelete: Cascade)\n\n  @@index([tradieId])\n  @@index([status])\n  @@index([type])\n  @@map(\"tradie_documents\")\n}\n\nmodel TradiePortfolio {\n  id             String        @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId       String        @db.Uuid\n  title          String\n  description    String?       @db.Text\n  beforeImageUrl String?\n  afterImageUrl  String?\n  category       TradeCategory\n  completedAt    DateTime?\n  createdAt      DateTime      @default(now())\n\n  tradie TradieProfile @relation(fields: [tradieId], references: [id], onDelete: Cascade)\n\n  @@index([tradieId])\n  @@index([category])\n  @@map(\"tradie_portfolios\")\n}\n\n/// Display configuration for trade categories (separate from the TradeCategory enum)\nmodel TradeCategoryConfig {\n  id                 String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  name               String\n  slug               String  @unique\n  icon               String?\n  description        String? @db.Text\n  emergencyAvailable Boolean @default(true)\n  displayOrder       Int     @default(0)\n  isActive           Boolean @default(true)\n\n  @@index([slug])\n  @@index([isActive])\n  @@index([displayOrder])\n  @@map(\"trade_category_configs\")\n}\n\nmodel Availability {\n  id          String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId    String  @db.Uuid\n  dayOfWeek   Int // 0 = Sunday … 6 = Saturday\n  startTime   String // \"HH:MM\" 24-hour\n  endTime     String // \"HH:MM\" 24-hour\n  isAvailable Boolean @default(true)\n\n  tradie TradieProfile @relation(fields: [tradieId], references: [id], onDelete: Cascade)\n\n  @@unique([tradieId, dayOfWeek])\n  @@index([tradieId])\n  @@map(\"availability\")\n}\n\nmodel EmergencySettings {\n  id                  String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId            String   @unique @db.Uuid\n  isAvailable         Boolean  @default(false)\n  maxRadius           Int      @default(25)\n  responseTimeMinutes Int      @default(30)\n  surchargePercent    Decimal  @default(50) @db.Decimal(5, 2)\n  autoAccept          Boolean  @default(false)\n  updatedAt           DateTime @updatedAt\n\n  tradie TradieProfile @relation(fields: [tradieId], references: [id], onDelete: Cascade)\n\n  @@map(\"emergency_settings\")\n}\n\n// ─── Location & Address ───────────────────────────────────────────────────────\n\nmodel Address {\n  id                String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId            String    @db.Uuid\n  customerProfileId String?   @db.Uuid\n  label             String?\n  street            String\n  suburb            String\n  city              String\n  state             String\n  postcode          String\n  country           String    @default(\"AU\")\n  latitude          Decimal?  @db.Decimal(10, 7)\n  longitude         Decimal?  @db.Decimal(10, 7)\n  isDefault         Boolean   @default(false)\n  deletedAt         DateTime?\n  createdAt         DateTime  @default(now())\n\n  user            User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  customerProfile CustomerProfile? @relation(\"CustomerAddresses\", fields: [customerProfileId], references: [id])\n  jobs            Job[]\n\n  @@index([userId])\n  @@index([customerProfileId])\n  @@index([deletedAt])\n  @@map(\"addresses\")\n}\n\nmodel SavedTradie {\n  id         String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  customerId String   @db.Uuid\n  tradieId   String   @db.Uuid\n  createdAt  DateTime @default(now())\n\n  customer CustomerProfile @relation(fields: [customerId], references: [id], onDelete: Cascade)\n\n  @@unique([customerId, tradieId])\n  @@index([customerId])\n  @@index([tradieId])\n  @@map(\"saved_tradies\")\n}\n\n// ─── Jobs ─────────────────────────────────────────────────────────────────────\n\nmodel Job {\n  id                 String        @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  customerId         String        @db.Uuid\n  tradieId           String?       @db.Uuid\n  addressId          String?       @db.Uuid\n  title              String\n  description        String        @db.Text\n  category           TradeCategory\n  status             JobStatus     @default(OPEN)\n  priority           JobPriority   @default(STANDARD)\n  isEmergency        Boolean       @default(false)\n  scheduledFor       DateTime?\n  estimatedHours     Decimal?      @db.Decimal(5, 2)\n  agreedPrice        Decimal?      @db.Decimal(10, 2)\n  finalPrice         Decimal?      @db.Decimal(10, 2)\n  platformFee        Decimal?      @db.Decimal(10, 2)\n  tradieEarnings     Decimal?      @db.Decimal(10, 2)\n  aiMatchScore       Decimal?      @db.Decimal(5, 4)\n  aiSuggestedTradies String[]      @db.Uuid\n  claimedAt          DateTime?\n  startedAt          DateTime?\n  completedAt        DateTime?\n  cancelledAt        DateTime?\n  cancelReason       String?\n  budgetMin          Decimal?      @db.Decimal(10, 2)\n  budgetMax          Decimal?      @db.Decimal(10, 2)\n  complexity         JobComplexity @default(MEDIUM)\n  mediaUrls          String[]\n  voiceNoteUrl       String?\n  preferredTime      String?\n  leadPrice          Decimal?      @db.Decimal(8, 2)\n  matchingBatchNo    Int           @default(0)\n  aiProcessedAt      DateTime?\n  offerExpiresAt     DateTime?\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  customer            CustomerProfile      @relation(\"CustomerJobs\", fields: [customerId], references: [id])\n  tradie              TradieProfile?       @relation(\"TradieJobs\", fields: [tradieId], references: [id])\n  address             Address?             @relation(fields: [addressId], references: [id])\n  claims              JobClaim[]\n  messages            Message[]\n  images              JobImage[]\n  timeline            JobStatusHistory[]\n  payment             Payment?\n  review              Review?\n  dispute             Dispute?\n  matchingQueue       JobMatchingQueue[]\n  events              JobEvent[]\n  aiInsight           AIJobInsight?\n  reviewRequest       ReviewRequest?\n  emergencyAssessment EmergencyAssessment?\n  aiConversation      AIConversation?\n\n  @@index([customerId])\n  @@index([tradieId])\n  @@index([status])\n  @@index([category])\n  @@index([priority])\n  @@index([isEmergency])\n  @@index([scheduledFor])\n  @@index([createdAt])\n  // Composite indexes for common filtered queries\n  @@index([status, category])\n  @@index([status, category, createdAt])\n  @@index([status, isEmergency])\n  @@index([tradieId, status])\n  @@index([customerId, status])\n  @@index([status, createdAt])\n  @@map(\"jobs\")\n}\n\nmodel JobClaim {\n  id             String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId          String    @db.Uuid\n  tradieId       String    @db.Uuid\n  message        String?   @db.Text\n  quotedPrice    Decimal   @db.Decimal(10, 2)\n  estimatedHours Decimal?  @db.Decimal(5, 2)\n  isAccepted     Boolean   @default(false)\n  acceptedAt     DateTime?\n  expiresAt      DateTime?\n  createdAt      DateTime  @default(now())\n\n  job    Job           @relation(fields: [jobId], references: [id], onDelete: Cascade)\n  tradie TradieProfile @relation(fields: [tradieId], references: [id])\n\n  @@index([jobId])\n  @@index([tradieId])\n  @@index([isAccepted])\n  @@map(\"job_claims\")\n}\n\nmodel JobStatusHistory {\n  id         String     @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId      String     @db.Uuid\n  fromStatus JobStatus?\n  toStatus   JobStatus\n  note       String?\n  changedBy  String     @db.Uuid\n  createdAt  DateTime   @default(now())\n\n  job Job @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  @@index([jobId])\n  @@index([createdAt])\n  @@map(\"job_status_history\")\n}\n\nmodel JobImage {\n  id         String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId      String   @db.Uuid\n  url        String\n  type       String // 'BEFORE' | 'AFTER' | 'PROGRESS' | 'ISSUE'\n  uploadedBy String   @db.Uuid\n  createdAt  DateTime @default(now())\n\n  job Job @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  @@index([jobId])\n  @@index([type])\n  @@map(\"job_images\")\n}\n\n// ─── Reviews ──────────────────────────────────────────────────────────────────\n\nmodel Review {\n  id           String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId        String    @unique @db.Uuid\n  reviewerId   String    @db.Uuid\n  revieweeId   String    @db.Uuid\n  rating       Int // 1–5\n  title        String?\n  body         String?   @db.Text\n  isPublic     Boolean   @default(true)\n  responseText String?   @db.Text\n  respondedAt  DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  job      Job  @relation(fields: [jobId], references: [id])\n  reviewer User @relation(\"ReviewsGiven\", fields: [reviewerId], references: [id])\n  reviewee User @relation(\"ReviewsReceived\", fields: [revieweeId], references: [id])\n\n  @@index([revieweeId])\n  @@index([reviewerId])\n  @@index([rating])\n  @@index([isPublic])\n  @@map(\"reviews\")\n}\n\n// ─── Messaging ────────────────────────────────────────────────────────────────\n\nmodel Message {\n  id          String        @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId       String        @db.Uuid\n  senderId    String        @db.Uuid\n  receiverId  String?       @db.Uuid\n  content     String        @db.Text\n  type        MessageType   @default(TEXT)\n  status      MessageStatus @default(SENT)\n  mediaUrl    String?\n  mediaType   String?\n  isSystem    Boolean       @default(false)\n  deletedAt   DateTime?\n  deliveredAt DateTime?\n  readAt      DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  job Job @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  @@index([jobId])\n  @@index([senderId])\n  @@index([receiverId])\n  @@index([createdAt])\n  @@map(\"messages\")\n}\n\n// ─── Notifications ────────────────────────────────────────────────────────────\n\nmodel Notification {\n  id         String           @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId     String           @db.Uuid\n  jobId      String?          @db.Uuid\n  type       NotificationType\n  title      String\n  body       String           @db.Text\n  data       Json?\n  status     NotifStatus      @default(PENDING)\n  channel    NotifChannel     @default(IN_APP)\n  readAt     DateTime?\n  sentAt     DateTime?\n  failedAt   DateTime?\n  retryCount Int              @default(0)\n  createdAt  DateTime         @default(now())\n\n  @@index([userId])\n  @@index([status])\n  @@index([type])\n  @@index([jobId])\n  @@index([createdAt])\n  // Composite for \"unread notifications for user\" — most common notification query\n  @@index([userId, readAt])\n  @@index([userId, createdAt])\n  @@index([userId, readAt, createdAt])\n  @@map(\"notifications\")\n}\n\n// ─── Payments ─────────────────────────────────────────────────────────────────\n\nmodel Payment {\n  id                    String        @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId                 String        @unique @db.Uuid\n  customerId            String        @db.Uuid\n  tradieId              String        @db.Uuid\n  amount                Decimal       @db.Decimal(10, 2)\n  platformFee           Decimal       @db.Decimal(10, 2)\n  tradieAmount          Decimal       @db.Decimal(10, 2)\n  currency              String        @default(\"AUD\")\n  status                PaymentStatus @default(PENDING)\n  stripePaymentIntentId String?       @unique\n  stripeTransferId      String?\n  stripeCustomerId      String?\n  paidAt                DateTime?\n  releasedAt            DateTime?\n  refundedAt            DateTime?\n  refundAmount          Decimal?      @db.Decimal(10, 2)\n  refundReason          String?\n  disputeId             String?       @db.Uuid\n  createdAt             DateTime      @default(now())\n  updatedAt             DateTime      @updatedAt\n\n  job Job @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  @@index([customerId])\n  @@index([tradieId])\n  @@index([status])\n  @@index([createdAt])\n  @@index([status, createdAt])\n  @@map(\"payments\")\n}\n\n// ─── Subscriptions ────────────────────────────────────────────────────────────\n\nmodel Subscription {\n  id                   String             @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId               String             @unique @db.Uuid\n  tier                 SubscriptionTier   @default(FREE)\n  status               SubscriptionStatus @default(ACTIVE)\n  stripeSubscriptionId String?\n  stripePriceId        String?\n  currentPeriodStart   DateTime?\n  currentPeriodEnd     DateTime?\n  cancelAtPeriodEnd    Boolean            @default(false)\n  createdAt            DateTime           @default(now())\n  updatedAt            DateTime           @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([status])\n  @@index([tier])\n  @@map(\"subscriptions\")\n}\n\n// ─── Credits & Wallet ─────────────────────────────────────────────────────────\n\nmodel CreditsWallet {\n  id             String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId         String   @unique @db.Uuid\n  balance        Decimal  @default(0) @db.Decimal(10, 2)\n  lifetimeEarned Decimal  @default(0) @db.Decimal(12, 2)\n  lifetimeSpent  Decimal  @default(0) @db.Decimal(12, 2)\n  updatedAt      DateTime @updatedAt\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  transactions Transaction[]\n\n  @@map(\"credits_wallets\")\n}\n\nmodel Transaction {\n  id            String          @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  walletId      String          @db.Uuid\n  type          TransactionType\n  amount        Decimal         @db.Decimal(10, 2)\n  balanceAfter  Decimal         @db.Decimal(10, 2)\n  description   String?\n  referenceId   String?\n  referenceType String?\n  metadata      Json?\n  createdAt     DateTime        @default(now())\n\n  wallet CreditsWallet @relation(fields: [walletId], references: [id], onDelete: Cascade)\n\n  @@index([walletId])\n  @@index([type])\n  @@index([createdAt])\n  @@map(\"transactions\")\n}\n\n// ─── Tradie Credentials ───────────────────────────────────────────────────────\n\nmodel Licence {\n  id            String             @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId      String             @db.Uuid\n  licenceType   String\n  licenceNumber String\n  state         String\n  expiresAt     DateTime?\n  documentUrl   String?\n  status        VerificationStatus @default(PENDING)\n  verifiedAt    DateTime?\n  createdAt     DateTime           @default(now())\n\n  tradie TradieProfile @relation(fields: [tradieId], references: [id], onDelete: Cascade)\n\n  @@index([tradieId])\n  @@index([status])\n  @@map(\"licences\")\n}\n\nmodel Insurance {\n  id           String             @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId     String             @db.Uuid\n  insurer      String\n  policyNumber String\n  coverType    String\n  coverAmount  Decimal            @db.Decimal(12, 2)\n  expiresAt    DateTime\n  documentUrl  String?\n  status       VerificationStatus @default(PENDING)\n  verifiedAt   DateTime?\n  createdAt    DateTime           @default(now())\n\n  tradie TradieProfile @relation(fields: [tradieId], references: [id], onDelete: Cascade)\n\n  @@index([tradieId])\n  @@index([status])\n  @@map(\"insurances\")\n}\n\nmodel Certification {\n  id          String             @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId    String             @db.Uuid\n  name        String\n  issuedBy    String\n  issuedAt    DateTime\n  expiresAt   DateTime?\n  documentUrl String?\n  status      VerificationStatus @default(PENDING)\n  createdAt   DateTime           @default(now())\n\n  tradie TradieProfile @relation(fields: [tradieId], references: [id], onDelete: Cascade)\n\n  @@index([tradieId])\n  @@index([status])\n  @@map(\"certifications\")\n}\n\n// ─── New Enums ────────────────────────────────────────────────────────────────\n\nenum MatchStatus {\n  PENDING\n  SENT\n  ACCEPTED\n  DECLINED\n  EXPIRED\n  FALLBACK\n}\n\nenum JobEventType {\n  CREATED\n  AI_PROCESSED\n  MATCHING_STARTED\n  OFFER_SENT\n  OFFER_ACCEPTED\n  OFFER_DECLINED\n  OFFER_EXPIRED\n  REASSIGNED\n  TRADIE_EN_ROUTE\n  TRADIE_ARRIVED\n  WORK_STARTED\n  WORK_COMPLETED\n  PAYMENT_REQUESTED\n  PAYMENT_RECEIVED\n  DISPUTED\n  CANCELLED\n}\n\nenum OnlineStatus {\n  ONLINE\n  OFFLINE\n  BUSY\n  EMERGENCY_ONLY\n  AWAY\n}\n\nenum JobComplexity {\n  SIMPLE\n  MEDIUM\n  COMPLEX\n}\n\n// ─── New Models ───────────────────────────────────────────────────────────────\n\nmodel JobMatchingQueue {\n  id            String      @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId         String      @db.Uuid\n  tradieId      String      @db.Uuid\n  batchNumber   Int         @default(1)\n  matchScore    Decimal     @db.Decimal(8, 4)\n  distanceKm    Decimal?    @db.Decimal(8, 2)\n  status        MatchStatus @default(PENDING)\n  sentAt        DateTime?\n  respondedAt   DateTime?\n  expiresAt     DateTime?\n  declineReason String?\n  createdAt     DateTime    @default(now())\n\n  job Job @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  @@index([jobId])\n  @@index([tradieId])\n  @@index([status])\n  @@index([batchNumber])\n  @@index([expiresAt])\n  @@index([jobId, status])\n  @@map(\"job_matching_queue\")\n}\n\nmodel JobEvent {\n  id        String       @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId     String       @db.Uuid\n  type      JobEventType\n  actorId   String?      @db.Uuid\n  actorRole Role?\n  metadata  Json?\n  createdAt DateTime     @default(now())\n\n  job Job @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  @@index([jobId])\n  @@index([type])\n  @@index([createdAt])\n  @@map(\"job_events\")\n}\n\nmodel TradieRealtimeStatus {\n  id               String       @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId         String       @unique @db.Uuid\n  onlineStatus     OnlineStatus @default(OFFLINE)\n  lastHeartbeatAt  DateTime?\n  currentJobId     String?      @db.Uuid\n  activeJobCount   Int          @default(0)\n  travelRadiusKm   Int          @default(25)\n  currentLatitude  Decimal?     @db.Decimal(10, 7)\n  currentLongitude Decimal?     @db.Decimal(10, 7)\n  isAutoAccept     Boolean      @default(false)\n  updatedAt        DateTime     @updatedAt\n\n  @@index([onlineStatus])\n  @@index([lastHeartbeatAt])\n  @@map(\"tradie_realtime_status\")\n}\n\nmodel AIJobInsight {\n  id                  String        @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId               String        @unique @db.Uuid\n  rawInput            String        @db.Text\n  extractedCategory   TradeCategory\n  complexity          JobComplexity @default(MEDIUM)\n  urgencyScore        Int\n  confidenceScore     Int\n  isEmergencyDetected Boolean       @default(false)\n  emergencyIndicators String[]\n  suggestedTitle      String\n  professionalSummary String        @db.Text\n  suggestedMaterials  String[]\n  estimatedPriceMin   Decimal?      @db.Decimal(10, 2)\n  estimatedPriceMax   Decimal?      @db.Decimal(10, 2)\n  leadPrice           Decimal?      @db.Decimal(8, 2)\n  suggestedTrades     String[]\n  imageAnalysis       Json?\n  voiceTranscript     String?       @db.Text\n  modelUsed           String?\n  processingMs        Int?\n  createdAt           DateTime      @default(now())\n  updatedAt           DateTime      @updatedAt\n\n  job Job @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  @@index([jobId])\n  @@index([extractedCategory])\n  @@index([urgencyScore])\n  @@map(\"ai_job_insights\")\n}\n\n// ─── Financial Extension ──────────────────────────────────────────────────────\n\nenum PayoutStatus {\n  PENDING\n  PROCESSING\n  PAID\n  FAILED\n  HELD\n  CANCELLED\n}\n\nenum SurgeFactor {\n  NONE\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nenum CreditTransactionType {\n  PURCHASE\n  JOB_DEDUCTION\n  BONUS\n  REFUND\n  ADMIN_ADJUSTMENT\n  REFERRAL\n  SUBSCRIPTION_CREDIT\n}\n\nmodel Payout {\n  id               String       @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId         String       @db.Uuid\n  jobId            String?      @db.Uuid\n  amount           Decimal      @db.Decimal(10, 2)\n  currency         String       @default(\"AUD\")\n  status           PayoutStatus @default(PENDING)\n  stripeTransferId String?      @unique\n  stripePayoutId   String?\n  scheduledFor     DateTime?\n  processedAt      DateTime?\n  failureReason    String?\n  isHeld           Boolean      @default(false)\n  heldReason       String?\n  heldBy           String?      @db.Uuid\n  metadata         Json?\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n\n  @@index([tradieId])\n  @@index([status])\n  @@index([jobId])\n  @@index([createdAt])\n  @@map(\"payouts\")\n}\n\nmodel CreditPackage {\n  id            String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  name          String\n  credits       Int\n  priceAud      Decimal  @db.Decimal(8, 2)\n  bonusCredits  Int      @default(0)\n  stripePriceId String?\n  isActive      Boolean  @default(true)\n  isPopular     Boolean  @default(false)\n  displayOrder  Int      @default(0)\n  createdAt     DateTime @default(now())\n\n  @@index([isActive])\n  @@index([displayOrder])\n  @@map(\"credit_packages\")\n}\n\nmodel CreditLedger {\n  id           String                @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId     String                @db.Uuid\n  type         CreditTransactionType\n  credits      Int\n  balanceAfter Int\n  jobId        String?               @db.Uuid\n  packageId    String?               @db.Uuid\n  referenceId  String?\n  description  String\n  metadata     Json?\n  createdAt    DateTime              @default(now())\n\n  @@index([tradieId])\n  @@index([type])\n  @@index([jobId])\n  @@index([createdAt])\n  @@map(\"credit_ledger\")\n}\n\nmodel PlatformConfig {\n  id        String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  key       String   @unique\n  value     String\n  category  String   @default(\"general\")\n  updatedBy String?  @db.Uuid\n  updatedAt DateTime @updatedAt\n\n  @@index([category])\n  @@map(\"platform_config\")\n}\n\nmodel SurgePricingRule {\n  id              String      @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  name            String\n  factor          SurgeFactor\n  multiplier      Decimal     @db.Decimal(4, 2)\n  startHour       Int? // 0-23, null = always\n  endHour         Int? // 0-23, null = always\n  daysOfWeek      Int[] // 0=Sun … 6=Sat, empty = all days\n  tradeCategories String[] // empty = all trades\n  isActive        Boolean     @default(true)\n  priority        Int         @default(0)\n  createdAt       DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  @@index([isActive])\n  @@index([factor])\n  @@map(\"surge_pricing_rules\")\n}\n\n// ─── Real-Time Communication Extension — Enums & New Models ──────────────────\n\nenum MessageType {\n  TEXT\n  IMAGE\n  FILE\n  SYSTEM\n  STATUS_UPDATE\n  VOICE\n}\n\nenum MessageStatus {\n  SENT\n  DELIVERED\n  READ\n  FAILED\n}\n\nenum NotifStatus {\n  PENDING\n  SENT\n  FAILED\n  READ\n}\n\nenum NotifChannel {\n  IN_APP\n  EMAIL\n  PUSH\n  SMS\n}\n\nmodel NotificationPreference {\n  id                String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId            String   @unique @db.Uuid\n  emailEnabled      Boolean  @default(true)\n  pushEnabled       Boolean  @default(true)\n  smsEnabled        Boolean  @default(false)\n  quietHoursEnabled Boolean  @default(false)\n  quietHoursStart   Int?\n  quietHoursEnd     Int?\n  disabledTypes     String[]\n  updatedAt         DateTime @updatedAt\n\n  @@map(\"notification_preferences\")\n}\n\nmodel LocationTracking {\n  id        String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId  String   @db.Uuid\n  jobId     String?  @db.Uuid\n  latitude  Decimal  @db.Decimal(10, 7)\n  longitude Decimal  @db.Decimal(10, 7)\n  accuracy  Float?\n  heading   Float?\n  speed     Float?\n  createdAt DateTime @default(now())\n\n  @@index([tradieId])\n  @@index([jobId])\n  @@index([createdAt])\n  @@map(\"location_tracking\")\n}\n\n// ─── Admin Intelligence Extension ────────────────────────────────────────────\n\nenum FraudFlagType {\n  FAKE_JOB\n  DUPLICATE_ACCOUNT\n  PAYMENT_ABUSE\n  EXCESSIVE_REFUNDS\n  LOCATION_SPOOFING\n  FAKE_REVIEW\n  BOT_ACTIVITY\n  SUSPICIOUS_MESSAGING\n  TRADIE_COLLUSION\n  EXCESSIVE_CANCELLATIONS\n  MULTI_ACCOUNT\n  OTHER\n}\n\nenum FraudSeverity {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nenum FraudFlagStatus {\n  PENDING\n  UNDER_REVIEW\n  RESOLVED_SAFE\n  RESOLVED_FRAUD\n  ESCALATED\n  AUTO_SUSPENDED\n}\n\nenum DisputeReason {\n  INCOMPLETE_WORK\n  NO_SHOW\n  PAYMENT_DISAGREEMENT\n  DAMAGE_CLAIM\n  REFUND_REQUEST\n  EMERGENCY_COMPLAINT\n  QUALITY_ISSUE\n  OTHER\n}\n\nenum DisputeStatus {\n  OPEN\n  UNDER_REVIEW\n  AWAITING_EVIDENCE\n  MEDIATION\n  RESOLVED_CUSTOMER\n  RESOLVED_TRADIE\n  RESOLVED_SPLIT\n  CLOSED\n  ESCALATED\n}\n\nenum ModerationActionType {\n  WARNING\n  TEMPORARY_SUSPENSION\n  PERMANENT_SUSPENSION\n  ACCOUNT_REINSTATEMENT\n  PROFILE_FLAG\n  REVIEW_REMOVAL\n  PAYOUT_HOLD\n  PAYOUT_RELEASE\n  VERIFICATION_APPROVED\n  VERIFICATION_REJECTED\n  TRUST_SCORE_OVERRIDE\n  FRAUD_FLAG_DISMISSED\n  FRAUD_FLAG_CONFIRMED\n}\n\nenum TicketStatus {\n  OPEN\n  IN_PROGRESS\n  WAITING_CUSTOMER\n  RESOLVED\n  CLOSED\n}\n\nenum TicketPriority {\n  LOW\n  NORMAL\n  HIGH\n  URGENT\n}\n\nenum TicketCategory {\n  PAYMENT\n  JOB_ISSUE\n  ACCOUNT\n  TECHNICAL\n  FRAUD\n  OTHER\n}\n\nenum AlertType {\n  FRAUD_SPIKE\n  PAYMENT_FAILURE\n  DISPATCH_FAILURE\n  UNUSUAL_REFUNDS\n  SYSTEM_ERROR\n  REVENUE_DROP\n  HIGH_DISPUTE_RATE\n  TRADIE_SHORTAGE\n}\n\nenum AlertSeverity {\n  INFO\n  WARNING\n  CRITICAL\n}\n\nenum AlertStatus {\n  ACTIVE\n  DISMISSED\n  RESOLVED\n}\n\nmodel TrustScoreHistory {\n  id            String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  tradieId      String   @db.Uuid\n  score         Int\n  previousScore Int?\n  reason        String\n  jobId         String?  @db.Uuid\n  adminId       String?  @db.Uuid\n  metadata      Json?\n  createdAt     DateTime @default(now())\n\n  @@index([tradieId])\n  @@index([createdAt])\n  @@map(\"trust_score_history\")\n}\n\nmodel FraudFlag {\n  id           String          @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId       String          @db.Uuid\n  type         FraudFlagType\n  severity     FraudSeverity\n  riskScore    Int\n  status       FraudFlagStatus @default(PENDING)\n  title        String\n  description  String          @db.Text\n  evidence     Json?\n  jobId        String?         @db.Uuid\n  reviewedBy   String?         @db.Uuid\n  reviewedAt   DateTime?\n  resolvedAt   DateTime?\n  autoDetected Boolean         @default(true)\n  createdAt    DateTime        @default(now())\n  updatedAt    DateTime        @updatedAt\n\n  @@index([userId])\n  @@index([status])\n  @@index([type])\n  @@index([severity])\n  @@index([createdAt])\n  @@map(\"fraud_flags\")\n}\n\nmodel Dispute {\n  id           String        @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId        String        @unique @db.Uuid\n  customerId   String        @db.Uuid\n  tradieId     String        @db.Uuid\n  reason       DisputeReason\n  status       DisputeStatus @default(OPEN)\n  title        String\n  description  String        @db.Text\n  evidenceUrls String[]\n  adminNotes   String?       @db.Text\n  resolution   String?       @db.Text\n  refundAmount Decimal?      @db.Decimal(10, 2)\n  assignedTo   String?       @db.Uuid\n  resolvedBy   String?       @db.Uuid\n  resolvedAt   DateTime?\n  dueBy        DateTime?\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n\n  job Job @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  @@index([customerId])\n  @@index([tradieId])\n  @@index([status])\n  @@index([createdAt])\n  @@index([status, createdAt])\n  @@map(\"disputes\")\n}\n\nmodel ModerationAction {\n  id           String               @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  adminId      String               @db.Uuid\n  targetUserId String               @db.Uuid\n  actionType   ModerationActionType\n  reason       String\n  metadata     Json?\n  expiresAt    DateTime?\n  createdAt    DateTime             @default(now())\n\n  @@index([adminId])\n  @@index([targetUserId])\n  @@index([actionType])\n  @@index([createdAt])\n  @@map(\"moderation_actions\")\n}\n\nmodel AdminAuditLog {\n  id        String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  adminId   String   @db.Uuid\n  action    String\n  entity    String\n  entityId  String?\n  metadata  Json?\n  ipAddress String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([adminId])\n  @@index([entity])\n  @@index([createdAt])\n  @@map(\"admin_audit_log\")\n}\n\nmodel SupportTicket {\n  id          String         @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId      String         @db.Uuid\n  jobId       String?        @db.Uuid\n  subject     String\n  description String         @db.Text\n  status      TicketStatus   @default(OPEN)\n  priority    TicketPriority @default(NORMAL)\n  category    TicketCategory\n  assignedTo  String?        @db.Uuid\n  resolvedAt  DateTime?\n  closedAt    DateTime?\n  createdAt   DateTime       @default(now())\n  updatedAt   DateTime       @updatedAt\n\n  @@index([userId])\n  @@index([status])\n  @@index([priority])\n  @@index([assignedTo])\n  @@index([createdAt])\n  @@map(\"support_tickets\")\n}\n\nmodel SupportMessage {\n  id        String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  ticketId  String   @db.Uuid\n  senderId  String   @db.Uuid\n  isAdmin   Boolean  @default(false)\n  content   String   @db.Text\n  createdAt DateTime @default(now())\n\n  @@index([ticketId])\n  @@map(\"support_messages\")\n}\n\nmodel PlatformAlert {\n  id          String        @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  type        AlertType\n  severity    AlertSeverity\n  title       String\n  message     String        @db.Text\n  data        Json?\n  status      AlertStatus   @default(ACTIVE)\n  dismissedBy String?       @db.Uuid\n  dismissedAt DateTime?\n  createdAt   DateTime      @default(now())\n\n  @@index([type])\n  @@index([severity])\n  @@index([status])\n  @@index([createdAt])\n  @@map(\"platform_alerts\")\n}\n\n// ─── Phase 7: Growth Engine Enums ─────────────────────────────────────────────\n\nenum ReferralStatus {\n  PENDING\n  SIGNED_UP\n  COMPLETED\n  REWARDED\n  EXPIRED\n}\n\nenum ReferralRewardType {\n  CREDITS\n  SUBSCRIPTION_DISCOUNT\n  CASH_EQUIVALENT\n  FREE_LEADS\n}\n\nenum SEOPageType {\n  SUBURB_TRADE\n  EMERGENCY_SERVICE\n  TRADIE_PROFILE\n  SUBURB_LANDING\n  TRADE_LANDING\n  BLOG_ARTICLE\n  FAQ_PAGE\n}\n\nenum GrowthEventType {\n  PAGE_VIEW\n  CTA_CLICK\n  JOB_STARTED\n  JOB_COMPLETED\n  REFERRAL_SENT\n  REFERRAL_CONVERTED\n  REVIEW_SUBMITTED\n  SIGNUP_STARTED\n  SIGNUP_COMPLETED\n  TRADIE_SIGNUP_STARTED\n  TRADIE_SIGNUP_COMPLETED\n  TRADIE_FIRST_JOB\n  SUBURB_EXPANDED\n  CONTENT_GENERATED\n  EMAIL_OPENED\n  EMAIL_CLICKED\n  PUSH_CLICKED\n}\n\nenum CampaignType {\n  EMAIL\n  PUSH\n  SMS\n  REFERRAL\n  SEO\n  PAID_SOCIAL\n  RETARGETING\n}\n\nenum CampaignStatus {\n  DRAFT\n  ACTIVE\n  PAUSED\n  COMPLETED\n  ARCHIVED\n}\n\nenum ReviewRequestStatus {\n  PENDING\n  SENT\n  REVIEWED\n  DECLINED\n  EXPIRED\n}\n\n// ─── Phase 7: Growth Engine Models ────────────────────────────────────────────\n\nmodel Referral {\n  id            String             @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  inviterId     String             @db.Uuid\n  invitedEmail  String?\n  invitedUserId String?            @db.Uuid\n  code          String             @unique\n  rewardType    ReferralRewardType\n  rewardValue   Decimal            @default(0) @db.Decimal(10, 2)\n  status        ReferralStatus     @default(PENDING)\n  completedAt   DateTime?\n  rewardedAt    DateTime?\n  expiresAt     DateTime?\n  createdAt     DateTime           @default(now())\n  updatedAt     DateTime           @updatedAt\n\n  inviter     User  @relation(\"ReferralInviter\", fields: [inviterId], references: [id])\n  invitedUser User? @relation(\"ReferralInvited\", fields: [invitedUserId], references: [id])\n\n  @@index([inviterId])\n  @@index([code])\n  @@index([status])\n  @@index([invitedEmail])\n  @@map(\"referrals\")\n}\n\nmodel SEOPage {\n  id              String      @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  slug            String      @unique\n  pageType        SEOPageType\n  title           String\n  metaDescription String      @db.Text\n  h1              String\n  suburb          String?\n  state           String?\n  tradeCategory   String?\n  isEmergency     Boolean     @default(false)\n  content         Json?\n  faqContent      Json?\n  schemaMarkup    Json?\n  canonicalUrl    String?\n  publishedAt     DateTime?\n  lastGeneratedAt DateTime?\n  viewCount       Int         @default(0)\n  indexable       Boolean     @default(true)\n  createdAt       DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  @@index([slug])\n  @@index([pageType])\n  @@index([suburb])\n  @@index([tradeCategory])\n  @@index([publishedAt])\n  @@map(\"seo_pages\")\n}\n\nmodel GrowthEvent {\n  id        String          @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId    String?         @db.Uuid\n  sessionId String?\n  eventType GrowthEventType\n  page      String?\n  referrer  String?\n  suburb    String?\n  metadata  Json?\n  ipHash    String?\n  userAgent String?\n  createdAt DateTime        @default(now())\n\n  @@index([userId])\n  @@index([eventType])\n  @@index([suburb])\n  @@index([createdAt])\n  @@map(\"growth_events\")\n}\n\nmodel SuburbMetrics {\n  id                String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  suburb            String\n  state             String\n  postcode          String?\n  latitude          Float?\n  longitude         Float?\n  demandScore       Float     @default(0)\n  supplyScore       Float     @default(0)\n  conversionRate    Float     @default(0)\n  avgResponseTime   Float?\n  jobCount30d       Int       @default(0)\n  tradieCount       Int       @default(0)\n  isUnderserved     Boolean   @default(false)\n  expansionPriority Int       @default(0)\n  lastCalculatedAt  DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  @@unique([suburb, state])\n  @@index([demandScore])\n  @@index([supplyScore])\n  @@index([isUnderserved])\n  @@index([expansionPriority])\n  @@map(\"suburb_metrics\")\n}\n\nmodel MarketingCampaign {\n  id               String         @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  name             String\n  type             CampaignType\n  status           CampaignStatus @default(DRAFT)\n  targetAudience   Json?\n  content          Json?\n  scheduledAt      DateTime?\n  sentAt           DateTime?\n  recipientCount   Int            @default(0)\n  openCount        Int            @default(0)\n  clickCount       Int            @default(0)\n  conversionCount  Int            @default(0)\n  revenueGenerated Decimal        @default(0) @db.Decimal(10, 2)\n  costSpent        Decimal        @default(0) @db.Decimal(10, 2)\n  metadata         Json?\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n\n  @@index([type])\n  @@index([status])\n  @@index([scheduledAt])\n  @@map(\"marketing_campaigns\")\n}\n\nmodel ReviewRequest {\n  id             String              @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId          String              @unique @db.Uuid\n  customerId     String              @db.Uuid\n  tradieId       String              @db.Uuid\n  status         ReviewRequestStatus @default(PENDING)\n  sentAt         DateTime?\n  reviewedAt     DateTime?\n  reminderSentAt DateTime?\n  expiresAt      DateTime?\n  createdAt      DateTime            @default(now())\n\n  job Job @relation(fields: [jobId], references: [id])\n\n  @@unique([jobId, customerId])\n  @@index([customerId])\n  @@index([tradieId])\n  @@index([status])\n  @@map(\"review_requests\")\n}\n\nmodel ReferralProgram {\n  id                 String             @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  name               String\n  targetRole         Role\n  rewardType         ReferralRewardType\n  rewardValue        Decimal            @db.Decimal(10, 2)\n  inviterRewardType  ReferralRewardType\n  inviterRewardValue Decimal            @db.Decimal(10, 2)\n  isActive           Boolean            @default(true)\n  maxRewardsPerUser  Int                @default(10)\n  expiryDays         Int                @default(30)\n  conditions         Json?\n  createdAt          DateTime           @default(now())\n  updatedAt          DateTime           @updatedAt\n\n  @@map(\"referral_programs\")\n}\n\n// ─── Phase 8: Voice AI Enums ───────────────────────────────────────────────────\n\nenum CallStatus {\n  INITIATED\n  RINGING\n  IN_PROGRESS\n  AI_HANDLING\n  HUMAN_TAKEOVER\n  COMPLETED\n  FAILED\n  ABANDONED\n}\n\nenum CallDirection {\n  INBOUND\n  OUTBOUND\n}\n\nenum VoiceEventType {\n  CALL_STARTED\n  CALL_ANSWERED\n  SPEECH_DETECTED\n  TRANSCRIPTION_RECEIVED\n  EMERGENCY_DETECTED\n  JOB_CREATED\n  DISPATCH_TRIGGERED\n  TRADIE_ASSIGNED\n  HUMAN_TAKEOVER_REQUESTED\n  HUMAN_TOOK_OVER\n  CALL_ENDED\n  AI_CONFIDENCE_LOW\n  ESCALATION_TRIGGERED\n}\n\nenum RiskLevel {\n  SAFE\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n  LIFE_THREATENING\n}\n\nenum ConversationStatus {\n  ACTIVE\n  GATHERING_INFO\n  CONFIRMING\n  JOB_CREATED\n  DISPATCHING\n  COMPLETED\n  ABANDONED\n  ESCALATED\n}\n\n// ─── Phase 8: Voice AI Models ─────────────────────────────────────────────────\n\nmodel VoiceCall {\n  id              String        @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  twilioCallSid   String?       @unique\n  customerId      String?       @db.Uuid\n  phoneNumber     String\n  direction       CallDirection\n  status          CallStatus    @default(INITIATED)\n  duration        Int?\n  recordingUrl    String?\n  transcript      String?       @db.Text\n  urgencyScore    Int?\n  aiConfidence    Float?\n  jobId           String?       @db.Uuid\n  assignedAgentId String?       @db.Uuid\n  startedAt       DateTime      @default(now())\n  answeredAt      DateTime?\n  endedAt         DateTime?\n  metadata        Json?\n\n  customer     User?                @relation(\"CustomerVoiceCalls\", fields: [customerId], references: [id])\n  events       VoiceEvent[]\n  assessment   EmergencyAssessment?\n  conversation AIConversation?\n\n  @@index([customerId])\n  @@index([status])\n  @@index([startedAt])\n  @@index([status, startedAt])\n  @@index([twilioCallSid])\n  @@map(\"voice_calls\")\n}\n\nmodel VoiceEvent {\n  id         String         @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  callId     String         @db.Uuid\n  eventType  VoiceEventType\n  payload    Json?\n  confidence Float?\n  createdAt  DateTime       @default(now())\n\n  call VoiceCall @relation(fields: [callId], references: [id])\n\n  @@index([callId])\n  @@index([eventType])\n  @@index([createdAt])\n  @@map(\"voice_events\")\n}\n\nmodel EmergencyAssessment {\n  id                 String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId              String?   @unique @db.Uuid\n  callId             String?   @unique @db.Uuid\n  riskLevel          RiskLevel\n  emergencyScore     Int\n  detectedKeywords   String[]\n  tradeCategory      String?\n  recommendedAction  String    @db.Text\n  safetyInstructions String[]\n  autoDispatch       Boolean   @default(false)\n  adminAlerted       Boolean   @default(false)\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  job  Job?       @relation(fields: [jobId], references: [id])\n  call VoiceCall? @relation(fields: [callId], references: [id])\n\n  @@index([riskLevel])\n  @@index([emergencyScore])\n  @@index([createdAt])\n  @@map(\"emergency_assessments\")\n}\n\nmodel AIConversation {\n  id                String             @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  jobId             String?            @unique @db.Uuid\n  callId            String?            @unique @db.Uuid\n  sessionId         String             @unique\n  status            ConversationStatus @default(ACTIVE)\n  messages          Json\n  extractedEntities Json?\n  aiSummary         String?            @db.Text\n  tradeCategory     String?\n  urgencyScore      Int?\n  isEmergency       Boolean            @default(false)\n  jobData           Json?\n  turnCount         Int                @default(0)\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n\n  job  Job?       @relation(fields: [jobId], references: [id])\n  call VoiceCall? @relation(fields: [callId], references: [id])\n\n  @@index([sessionId])\n  @@index([status])\n  @@index([isEmergency])\n  @@map(\"ai_conversations\")\n}\n\n// ─── Stripe Webhook Idempotency ───────────────────────────────────────────────\n// Tracks processed Stripe event IDs so duplicate deliveries are safely skipped.\n// Works across multiple server instances and process restarts.\n\nmodel StripeProcessedEvent {\n  eventId     String   @id\n  processedAt DateTime @default(now())\n  eventType   String\n\n  @@index([processedAt])\n  @@map(\"stripe_processed_events\")\n}\n"
}

